    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint d, uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0);
        require(a > 0);
        require(a <= d);
        require(address(this).balance >= d);
        c.SetMinSum(d); if (__ESBMC_reverted()) return;
        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(c).balance;
        uint testBefore = address(this).balance;
        bool reverted;
        c.Collect(a); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && c.balances(address(this)) == balBefore - a && address(c).balance == etherBefore - a && address(this).balance == testBefore + a);
    }
    receive() external payable {}
