    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 d, uint256 a) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d > 0);
        vm.assume(a > 0);
        vm.assume(a <= d);
        vm.assume(address(this).balance >= d);
        try c.SetMinSum(d) {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint etherBefore = address(c).balance;
        uint testBefore = address(this).balance;
        bool reverted;
        try c.Collect(a) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balBefore - a && address(c).balance == etherBefore - a && address(this).balance == testBefore + a);
    }

    function testFuzz_run(uint256 d, uint256 a) public {
        _run(d, a);
    }

    receive() external payable {}
}
